const items = $input.all();

let senderRaw = '';
try {
  const webhookData = $('Webhook').first().json;
  senderRaw = String(webhookData.body?.data?.key?.remoteJid || webhookData.body?.sender || webhookData.body?.data?.remoteJid || '').split('@')[0];
} catch (e) {
  senderRaw = '';
}

// Extrai apenas os ultimos 8 digitos do remetente
const senderDigits = senderRaw.replace(/\D/g, '').slice(-8);

// Normaliza os numeros autorizados vindos do Supabase
const numbers = items
  .map(item => String(item.json?.whatsapp || item.json?.telefone || '').replace(/\D/g, '').slice(-8))
  .filter(digits => digits.length >= 8);

const isAuthorized = senderDigits.length >= 8 && numbers.includes(senderDigits);

return [{
  json: {
    isAuthorized,
    senderDigits,
    totalAutorizados: numbers.length
  }
}];
